import{_ as a}from"./chunks/thumb-09.DokM_eUU.js";import{_ as e,H as r,f as i,i as d}from"./chunks/framework.Cvt1eIE0.js";const b=JSON.parse('{"title":"Trae 使用教程：字节 AI IDE 安装与 Builder 工作流","description":"","frontmatter":{"title":"Trae 使用教程：字节 AI IDE 安装与 Builder 工作流","date":"2026-05-23T00:00:00.000Z","category":"技术","tags":["AI","Trae","教程"],"excerpt":"字节跳动 AI 编程 IDE Trae：安装、Builder/Chat、模型选择与和 Cursor 的差异。"},"headers":[],"relativePath":"posts/技术/trae-ai-ide-tutorial.md","filePath":"posts/技术/trae-ai-ide-tutorial.md"}'),s={name:"posts/技术/trae-ai-ide-tutorial.md"};function o(n,t,l,h,u,p){return r(),i("div",null,[...t[0]||(t[0]=[d('<img src="'+a+`" alt="配图" class="article-banner" loading="lazy"><h1 id="trae-使用教程" tabindex="-1">Trae 使用教程 <a class="header-anchor" href="#trae-使用教程" aria-label="Permalink to &quot;Trae 使用教程&quot;">​</a></h1><p><a href="https://www.trae.ai" target="_blank" rel="noreferrer">Trae</a> 是字节跳动推出的 <strong>AI-native 编程 IDE</strong>（海外版与国内版策略可能不同），整体形态接近 Cursor / Windsurf：内置对话、多文件生成、终端集成，并强调 <strong>Builder</strong> 模式——用自然语言驱动从需求到可运行项目的迭代。</p><p>本文是本站原创入门笔记；功能名称与配额以 Trae 官网为准。</p><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>希望<strong>一站式 IDE + Agent</strong>，不想自己拼 VS Code 扩展</li><li>需要同时试用 <strong>GPT / Claude / DeepSeek</strong> 等模型（以 Trae 当前支持列表为准）</li><li>国内网络环境下寻找 Cursor 的替代或补充</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>打开 Trae 官网，下载 <strong>macOS / Windows</strong> 安装包（注意芯片架构）。</li><li>注册并登录账号。</li><li>首次启动可选择导入 VS Code 主题/快捷键（若有该选项）。</li><li>在设置中选择默认模型与语言偏好。</li></ol><h2 id="界面与模式" tabindex="-1">界面与模式 <a class="header-anchor" href="#界面与模式" aria-label="Permalink to &quot;界面与模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>针对当前文件或选区问答、解释、小改</td></tr><tr><td><strong>Builder / Agent</strong></td><td>多文件、多步骤实现功能（名称随版本可能为 Builder、Agent 等）</td></tr><tr><td><strong>补全</strong></td><td>行级预测，写注释可提升建议质量</td></tr><tr><td><strong>终端</strong></td><td>内置终端跑测试、装依赖，Agent 可提议执行命令</td></tr></tbody></table><h2 id="推荐工作流" tabindex="-1">推荐工作流 <a class="header-anchor" href="#推荐工作流" aria-label="Permalink to &quot;推荐工作流&quot;">​</a></h2><h3 id="_1-小需求-chat" tabindex="-1">1. 小需求：Chat <a class="header-anchor" href="#_1-小需求-chat" aria-label="Permalink to &quot;1. 小需求：Chat&quot;">​</a></h3><p>「解释这段 Riverpod 为何 rebuild」「给这个 Widget 加 Semantics」——改前看清 diff。</p><h3 id="_2-功能需求-builder" tabindex="-1">2. 功能需求：Builder <a class="header-anchor" href="#_2-功能需求-builder" aria-label="Permalink to &quot;2. 功能需求：Builder&quot;">​</a></h3><p>输入结构化任务，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 lib/features/todo/ 实现：</span></span>
<span class="line"><span>- TodoListPage（Riverpod）</span></span>
<span class="line"><span>- 本地 Hive 存储</span></span>
<span class="line"><span>- 单元测试覆盖增删改</span></span>
<span class="line"><span>不要修改 lib/main.dart 的路由注册方式</span></span></code></pre></div><p>让 Builder 分步产出，<strong>每步跑 <code>flutter test</code></strong> 再进入下一步。</p><h3 id="_3-团队规范" tabindex="-1">3. 团队规范 <a class="header-anchor" href="#_3-团队规范" aria-label="Permalink to &quot;3. 团队规范&quot;">​</a></h3><p>在项目中维护说明文件（若 Trae 支持项目级 Rules / Instructions，将团队约定写入），包括：</p><ul><li>目录与命名</li><li>禁止修改 <code>generated/</code></li><li>必须跑的 CI 命令</li></ul><h2 id="与-cursor-windsurf-选型" tabindex="-1">与 Cursor / Windsurf 选型 <a class="header-anchor" href="#与-cursor-windsurf-选型" aria-label="Permalink to &quot;与 Cursor / Windsurf 选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Trae</th><th>Cursor</th><th>Windsurf</th></tr></thead><tbody><tr><td>出品</td><td>字节</td><td>Anysphere</td><td>Codeium</td></tr><tr><td>国内可用性</td><td>通常更友好</td><td>视网络而定</td><td>视网络而定</td></tr><tr><td>多模型</td><td>支持列表以官网为准</td><td>多模型</td><td>多模型</td></tr><tr><td>生态</td><td>较新</td><td>VS Code 迁移成熟</td><td>Cascade 特色</td></tr></tbody></table><p>建议用<strong>同一仓库、同一 issue</strong> 各试一天，比较 diff 质量与测试通过率，再定主力 IDE。</p><h2 id="与终端-agent-配合" tabindex="-1">与终端 Agent 配合 <a class="header-anchor" href="#与终端-agent-配合" aria-label="Permalink to &quot;与终端 Agent 配合&quot;">​</a></h2><p>Trae 负责日常编码；<strong>Claude Code / Gemini CLI / Codex</strong> 负责：</p><ul><li>大批量迁移、脚本生成</li><li>CI 里 Headless 任务（若产品支持）</li></ul><p>避免两套 Agent <strong>同时改同一分支</strong>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：Trae 和豆包 / 其他字节产品关系？</strong><br> A：同属字节 AI 产品线，账号与计费可能打通，以官方说明为准。</p><p><strong>Q：公司代码能用吗？</strong><br> A：查阅 Trae 隐私政策、是否支持私有化/企业版；涉密项目走合规审批。</p><p><strong>Q：已有 Cursor 还要装吗？</strong><br> A：不必。Trae 适合作为备选或国内环境主 IDE；工具贵精不贵多。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/posts/技术/cursor-ai-coding-tutorial.html">Cursor 使用教程</a></li><li><a href="/posts/技术/ai-coding-tools-index.html">AI 编程工具教程索引</a></li></ul><hr><p><em>Trae 功能与区域可用性以官网为准。</em></p>`,35)])])}const f=e(s,[["render",o]]);export{b as __pageData,f as default};
